function find(name){const k=nm(name);if(!k)return null;if(BY[k])return BY[k];const a=ALIAS[k];if(a&&BY[nm(a)])return BY[nm(a)];
  // "Kickapoo High School (Springfield)" style → try without the parenthetical, then with it as city
  const m=String(name).match(/^(.*?)\s*\((.*?)\)\s*$/);if(m){const k2=nm(m[1]);if(BY[nm(`${m[1]} (${m[2]})`)])return BY[nm(`${m[1]} (${m[2]})`)];if(ALIAS[k2]&&BY[nm(ALIAS[k2])])return BY[nm(ALIAS[k2])];if(BY[k2])return BY[k2]}
  return null}
